/**
 * OOXML round-trip baseline: shared types.
 *
 * The baseline exists so that "did we lose anything?" is a number, not an opinion. Samples are
 * generated by our own exporters (decision D7, 2026-10-29), so they prove self-consistency —
 * external files are a separate group and are never mixed into the same metric.
 */

export type BaselineTool = 'slide' | 'docx' | 'sheet';

/** Flat, numeric metrics only: JSON-diffable and stable across runs (never contains ids or times) */
export type Metrics = Record<string, number>;

export interface SampleIssue {
  code: string;
  count: number;
}

export interface SampleResult {
  id: string;
  tool: BaselineTool;
  title: string;
  /** Why a metric may legitimately differ (environment limits, known channel trade-offs) */
  notes?: string;
  /** Export + import both succeeded */
  ok: boolean;
  error?: string;
  /** Metrics of the document we generated */
  before: Metrics;
  /** Metrics of the document we got back after export → import */
  after: Metrics;
  /** Degradation reported by the tool's own fidelity channel */
  issues: SampleIssue[];
  /** Byte-level facts (zip part counts etc.); recorded but never compared to a golden */
  artifacts: Record<string, number>;
}

export interface BaselineReport {
  /** Informational only: the golden comparison ignores it */
  generatedAt: string;
  generator: string;
  total: number;
  samples: SampleResult[];
}

/** A metric that differs between golden and current run */
export interface MetricDiff {
  sample: string;
  key: string;
  golden: number;
  current: number;
}

export interface ReportDiff {
  addedSamples: string[];
  removedSamples: string[];
  changed: MetricDiff[];
  /** Issues that appeared / disappeared, keyed `sample:code` */
  addedIssues: string[];
  removedIssues: string[];
}
